import {parsePrompt,planStory,composeStory} from './compiler.mjs';import {prepareStory} from './native-adapter.mjs';
let dialog,host,prepared=null,controller=null,working=false,committing=false,version=null;
const by=id=>dialog.querySelector('#'+id);
function setStatus(text){by('storyStatus').textContent=text}
function controls(){for(const id of ['storyPrompt','storyGenerate','storyClose'])by(id).disabled=working;dialog.querySelectorAll('[data-example]').forEach(b=>b.disabled=working);by('storyCancel').hidden=!working||committing;by('storyAppend').disabled=working||!prepared;by('storyReplace').disabled=working||!prepared}
function invalidate(){prepared=null;by('storyResult').hidden=true;by('storyPreview').replaceChildren();controls()}
function showPlan(plan){by('storyResult').hidden=false;by('storySummary').textContent=plan.title+' · '+plan.count+' مشاهد · '+plan.seconds+' ثانية'+(plan.audience==='children'?' · صياغة للأطفال':'');by('storyNotes').replaceChildren(...plan.notes.map(text=>{const p=document.createElement('p');p.textContent=text;return p}));const sources=document.createElement('p');sources.append('المصادر: ');for(const s of plan.sources){const a=document.createElement('a');a.href=s.url;a.textContent=s.label;a.target='_blank';a.rel='noopener noreferrer';sources.append(a,' ')}by('storyNotes').append(sources)}
async function generate(event){event.preventDefault();if(working||host.busy())return;invalidate();let plan;try{plan=planStory(parsePrompt(by('storyPrompt').value))}catch(error){setStatus(error.message);return}working=true;controller=new AbortController();version=host.version();controls();showPlan(plan);by('storyProgress').hidden=false;by('storyProgress').value=0;host.begin();
 try{const descriptors=await composeStory(plan);const result=await prepareStory(descriptors,host,{signal:controller.signal,onProgress:(label,done,total)=>{setStatus(label);by('storyProgress').value=done/total*100;host.progress(label,done,total)}});if(controller.signal.aborted)throw new DOMException('Cancelled','AbortError');prepared={...result,plan,version};by('storyPreview').replaceChildren(...result.scenes.map((s,index)=>{const card=document.createElement('article'),img=document.createElement('img'),h=document.createElement('strong'),p=document.createElement('p');img.src=s.thumb;img.alt=plan.stages[index].title;h.textContent=(index+1)+'. '+s.name;p.textContent=plan.stages[index].caption+' · '+s.elementDocument.items.length+' عناصر';card.append(img,h,p);return card}));dialog.dataset.topic=plan.topic;dialog.dataset.sceneCount=String(result.scenes.length);by('storyResult').scrollIntoView({block:'start'});setStatus('القصة جاهزة للمراجعة. لم يتغير مشروعك بعد. أضفها أو ابدأ بها مشروعًا جديدًا.')}catch(error){prepared=null;setStatus(error.name==='AbortError'?'أُلغي التجهيز. لم يتغير مشروعك.':/fetch|imported|font|network/i.test(String(error.message||error))?'تعذّر تحميل ملفات القصة. تحقق من الاتصال. إن استمرت المشكلة، أعد فتح الصفحة؛ مشروعك لم يتغير.':'لم تُنشأ القصة: '+String(error.message||error))}finally{host.end();working=false;controller=null;by('storyProgress').hidden=true;controls()}}
async function apply(mode){if(!prepared||working||host.busy())return;if(mode==='replace'&&!window.confirm('سيُحفظ المشروع الحالي كنسخة مستردة قبل بدء القصة الجديدة. هل تريد المتابعة؟'))return;working=committing=true;controls();host.begin();try{await host.commit(prepared.scenes,{mode,title:prepared.plan.title,version:prepared.version});prepared=null;dialog.close()}catch(error){setStatus(String(error.message||error))}finally{host.end();working=committing=false;controls()}}
function cancel(){if(committing)return;if(working){controller?.abort();host.cancel();setStatus('جارٍ إلغاء التجهيز بأمان…')}else dialog.close()}
function create(){const link=document.createElement('link');link.rel='stylesheet';link.href=new URL('./composer.css',import.meta.url).href;document.head.append(link);dialog=document.createElement('dialog');dialog.className='storyComposer';dialog.id='storyDialog';dialog.setAttribute('aria-labelledby','storyHeading');dialog.innerHTML=`<header><div><small>تجربة مؤلف القصص</small><h2 id="storyHeading">من فكرة إلى قصة مرسومة</h2></div><button type="button" id="storyClose" aria-label="إغلاق">إغلاق</button></header><p class="storyScope">مؤلف محدود بالمكتبة، يعمل بالكود فقط. المتاح الآن: طوفان نوح ونمو شجرة من بذرة. بلا خدمة ذكاء اصطناعي خارجية أو نماذج توليد.</p><form id="storyForm"><label for="storyPrompt">ما القصة التي تريد شرحها؟</label><textarea id="storyPrompt" rows="3" maxlength="600" placeholder="اشرح طوفان نوح للأطفال في ٥ مشاهد خلال ٣٥ ثانية"></textarea><div class="storyExamples"><button type="button" data-example="noah">مثال: طوفان نوح</button><button type="button" data-example="plant">مثال: من بذرة إلى شجرة</button></div><p class="storyHint">يمكنك تحديد ٣ إلى ٥ مشاهد ومدة من ١٥ إلى ١٢٠ ثانية وكتابة «للأطفال». الأسلوب والألوان ثابتان. لا تُطبّق طلبات التفصيل خارج هذه الخيارات.</p><div class="actions"><button id="storyGenerate" class="primary" type="submit">إنشاء المشاهد للمراجعة</button><button id="storyCancel" hidden type="button">إلغاء التجهيز</button></div></form><p id="storyStatus" role="status" aria-live="polite">الحزم تُحمّل عند الطلب فقط، ولا تتغير ملفات مشروعك بمجرد التجربة.</p><progress id="storyProgress" max="100" hidden></progress><section id="storyResult" hidden><h3 id="storySummary"></h3><div id="storyNotes" class="storyNotes"></div><div id="storyPreview" class="storyPreview"></div><div class="storyApply actions"><button id="storyAppend" class="primary" type="button" disabled>إضافة إلى المشروع</button><button id="storyReplace" type="button" disabled>بدء مشروع جديد بالقصة</button></div><p class="storyHint">العناصر مستقلة على الخط الزمني ويمكن تعديل ترتيبها ومدتها. الحركة هي رسم وايت بورد، وليست محاكاة لحركة الحيوان أو الماء. لا تعليق صوتي مولد تلقائيًا.</p></section>`;document.body.append(dialog);by('storyForm').onsubmit=generate;by('storyClose').onclick=cancel;by('storyCancel').onclick=cancel;by('storyAppend').onclick=()=>apply('append');by('storyReplace').onclick=()=>apply('replace');by('storyPrompt').oninput=invalidate;dialog.addEventListener('cancel',event=>{event.preventDefault();cancel()});dialog.querySelectorAll('[data-example]').forEach(b=>b.onclick=()=>{by('storyPrompt').value=b.dataset.example==='noah'?'اشرح طوفان نوح للأطفال في ٥ مشاهد خلال ٣٥ ثانية':'اشرح نمو شجرة من بذرة للأطفال في ٤ مشاهد خلال ٢٨ ثانية';invalidate();setStatus('اضغط إنشاء المشاهد لمراجعة القصة قبل إضافتها.')})}
export async function open(api){host=api;if(!dialog)create();if(!dialog.open){dialog.showModal();by('storyPrompt').focus()}controls()}
